package com.turboio.androidtests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.util.Base64;
import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;

/** Real Android Keystore with synthetic settings in an isolated preferences file.
 * Opens the normal UI after checking login, never enables sync or reads journals. */
public final class MaterialSettingsProbe extends Instrumentation {
 private ClassLoader loader;private int checks;private String nonce;
 private Class<?> type(String name)throws Exception{return loader.loadClass("com.turboio.addon."+name);}
 private Object call(Object obj,String name,Class<?>[] types,Object...args)throws Exception{Class<?> c=obj instanceof Class?(Class<?>)obj:obj.getClass();Method m=c.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(obj instanceof Class?null:obj,args);}
 private void check(boolean good,String code){checks++;if(!good)throw new IllegalStateException(code);}
 private byte[] encode(Object config)throws Exception{return (byte[])call(config,"encode",new Class<?>[0]);}
 private void labels(View view,Set<String> labels,List<View> buttons){if(view instanceof TextView){String text=((TextView)view).getText().toString();if(Arrays.asList("资料同步","资料连接设置","尚未配置资料服务器","当前原厂账号与资料连接不一致，请核对账号和登记文件").contains(text))labels.add(text);if(text.equals("资料同步")&&view.isClickable())buttons.add(view);}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)labels(group.getChildAt(i),labels,buttons);}}
 @Override public void onCreate(Bundle args){super.onCreate(args);nonce=args.getString("probe_id","");start();}
 @Override public void onStart(){Bundle report=new Bundle();report.putString("probe_id",nonce);Context target=getTargetContext();String name="io_agent_material_probe_"+nonce;SharedPreferences isolated=target.getSharedPreferences(name,Context.MODE_PRIVATE);Map<String,?> before=new HashMap<>(target.getSharedPreferences("io_agent_materials_v1",Context.MODE_PRIVATE).getAll());try{
  check(nonce.matches("[a-f0-9]{32}")&&before.isEmpty(),"MATERIAL_PROBE_PREFLIGHT");loader=target.getClassLoader();Class<?> settings=type("MaterialSettings"),configType=type("MaterialConfig"),connectionType=type("MaterialConnection");Constructor<?> ctor=settings.getDeclaredConstructor(Context.class);ctor.setAccessible(true);Context wrapped=new ContextWrapper(target){@Override public SharedPreferences getSharedPreferences(String ignored,int mode){return isolated;}};Object store=ctor.newInstance(wrapped);check(call(store,"load",new Class<?>[0])==null,"MATERIAL_PROBE_NOT_EMPTY");
  JSONObject wire=new JSONObject().put("format","turboio-material-sync/1").put("base_url","https://synthetic.invalid/v1").put("owner_id","synthetic-material-settings").put("producer_id","synthetic-phone").put("server_id","synthetic-server").put("token",String.join("",Collections.nCopies(43,"A"))).put("token_id","00000000-0000-4000-8000-000000000001").put("expires_at",java.time.Instant.ofEpochMilli(System.currentTimeMillis()+3600000).toString());
  Object connection=call(connectionType,"parse",new Class<?>[]{byte[].class,long.class},wire.toString().getBytes(StandardCharsets.UTF_8),System.currentTimeMillis());Constructor<?> configCtor=configType.getDeclaredConstructor(connectionType,String.class,boolean.class);configCtor.setAccessible(true);Object config=configCtor.newInstance(connection,String.join("",Collections.nCopies(64,"a")),true);
  call(store,"save",new Class<?>[]{configType},config);String sealed=isolated.getString("sealed",null);check(sealed!=null&&!sealed.contains("synthetic")&&!sealed.contains(wire.getString("token")),"MATERIAL_SECRET_PLAINTEXT");check(Arrays.equals(encode(config),encode(call(ctor.newInstance(wrapped),"load",new Class<?>[0]))),"MATERIAL_REOPEN_MISMATCH");
  Object paused=call(config,"enabled",new Class<?>[]{boolean.class},false);call(store,"save",new Class<?>[]{configType},paused);check(Arrays.equals(encode(paused),encode(call(ctor.newInstance(wrapped),"load",new Class<?>[0]))),"MATERIAL_PAUSE_NOT_SAVED");String valid=isolated.getString("sealed",null);
  Object foreign=configCtor.newInstance(connection,String.join("",Collections.nCopies(64,"b")),true);boolean refused=false;try{call(store,"save",new Class<?>[]{configType},foreign);}catch(InvocationTargetException expected){refused=true;}check(refused&&valid.equals(isolated.getString("sealed",null)),"MATERIAL_REBIND_NOT_REFUSED");
  byte[] damaged=Base64.decode(valid,Base64.NO_WRAP);damaged[damaged.length-1]^=1;isolated.edit().putString("sealed",Base64.encodeToString(damaged,Base64.NO_WRAP)).commit();refused=false;try{call(store,"load",new Class<?>[0]);}catch(InvocationTargetException expected){refused=true;}check(refused,"MATERIAL_TAMPER_NOT_REFUSED");check(before.equals(target.getSharedPreferences("io_agent_materials_v1",Context.MODE_PRIVATE).getAll()),"REAL_MATERIAL_SETTINGS_CHANGED");
  check(target.deleteSharedPreferences(name),"MATERIAL_TEST_PREFS_NOT_REMOVED");
  report.putInt("checks_passed",checks);report.putBoolean("real_keystore",true);report.putBoolean("test_namespace_removed",true);report.putBoolean("real_settings_unchanged",true);report.putBoolean("sync_or_microphone_started",false);report.putBoolean("credentials_exported",false);finish(Activity.RESULT_OK,report);
 }catch(Throwable failed){while(failed.getCause()!=null)failed=failed.getCause();String code=failed.getMessage();report.putString("error",code!=null&&code.matches("[A-Z_]{3,90}")?code:failed.getClass().getSimpleName());report.putInt("checks_passed",checks);target.deleteSharedPreferences(name);finish(Activity.RESULT_CANCELED,report);}finally{target.deleteSharedPreferences(name);}}
}
